```js
const INVOICES = {
  'inv-1': { id: 'inv-1', total: 100, currency: 'USD', status: 'paid' }
};

export async function listTools() {
  return [
    {
      name: 'lookup_invoice',
      description: 'Look up an invoice by its invoice_id.',
      inputSchema: {
        type: 'object',
        properties: {
          invoice_id: { type: 'string', description: 'The invoice identifier.' }
        },
        required: ['invoice_id']
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name === 'lookup_invoice') {
    const { invoice_id } = args;
    if (typeof invoice_id !== 'string' || invoice_id.trim() === '') {
      const err = new Error('invoice_id is required and must be a non-empty string');
      err.code = 'INVALID_ARGUMENT';
      throw err;
    }
    const invoice = INVOICES[invoice_id];
    if (!invoice) {
      const err = new Error(`Invoice ${invoice_id} not found`);
      err.code = 'NOT_FOUND';
      throw err;
    }
    return { content: [{ type: 'text', text: JSON.stringify(invoice) }] };
  }
  const err = new Error(`Unknown tool: ${name}`);
  err.code = 'UNKNOWN_TOOL';
  throw err;
}
